INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.mural.subtitle','services','Historias en grandes muros');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.mural.description','services','Arte que transforma muros en relatos vivos. Composiciones originales, pensadas para dialogar con su espacio y su gente.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.escultura.subtitle','services','Forma que respira');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.escultura.description','services','Volumen, materia y carácter se encuentran en piezas únicas, creadas para habitar espacios con presencia y sensibilidad.');
